import React, { useState } from "react";
import { Link } from "react-router-dom";

function NavBar() {
  const [open, setOpne] = useState(false);
  const linkNames = [
    { name: "Home", url: "/" },
    { name: "Planets", url: "/planets" },
  ];
  return (
    <div className=" bg-transparent w-full sm:h-16 md:flex md:justify-around  p-5">
      <h1 className=" uppercase font-poppins text-2xl">solar explore</h1>
      <div className="  absolute  top-5 right-5 md:hidden" >
        <img
          className={`${open}` ? "flex cursor-pointer" : " hidden"}
          onClick={()=>{setOpne(!open)}}
          width="30"
          height="30"
          src="https://img.icons8.com/ios/50/FFFFFF/delete-sign--v1.png"
          alt="delete-sign--v1"
        />
        <img
          className={`${open}` ? "hidden" : "  flex cursor-pointer"}
          onClick={()=>{setOpne(!open)}}
          width="30"
          height="50"
          src="https://img.icons8.com/ios/50/FFFFFF/menu.png"
          alt="menu"
        />
      </div>
      <ul className=" md:flex ">
        {linkNames.map((item) => {
          return (
            <li className="mt-5 md:mt-0">
              <Link className=" md:me-10" to={item.url}>
                {item.name}
              </Link>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

export default NavBar;
